"""Handwritten deterministic stand-in for future model output; not LLM-generated."""
import pytest
from src.reservations import quote, cancellation_refund


def test_group_stay_combines_discounts_in_order():
    assert quote(7, 10000, guests=3, member=True) == 71820


def test_short_stay_includes_two_guests():
    assert quote(6, 10000, guests=2) == 60000


@pytest.mark.parametrize("days, expected", [(1, 0), (2, 50), (6, 50), (7, 101)])
def test_refund_thresholds(days, expected):
    assert cancellation_refund(101, days) == expected


def test_boolean_is_not_a_night_count():
    with pytest.raises(TypeError):
        quote(True, 10000)
